import { Component, DestroyRef, EventEmitter, inject, Input, OnChanges, Output, ViewEncapsulation } from '@angular/core';
import { FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatAutocompleteModule, MatAutocompleteSelectedEvent } from '@angular/material/autocomplete';
import { BehaviorSubject } from 'rxjs';
import { filter } from 'rxjs/operators';
import {
    NewPermissionEntity,
    PermissionEntity,
    NewPermission,
    IsSuggestedPermissionEntityValidator,
    InheritedPermissionEntity,
    Permission,
} from '@alfresco/adf-hx-content-services/services';
import { NgIf, NgFor, NgClass, KeyValuePipe } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatOptionModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
import { TranslatePipe } from '@ngx-translate/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { NewPermissionLabels } from '../models/permissions-label.model';

interface AddPermissionForm {
    search: FormControl<string>;
    permission: FormControl<NewPermission | undefined>;
}

@Component({
    selector: 'hxp-add-permission',
    templateUrl: './add-permission.component.html',
    styleUrls: ['./add-permission.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
    imports: [
        MatFormFieldModule,
        MatInputModule,
        FormsModule,
        MatAutocompleteModule,
        ReactiveFormsModule,
        MatIconModule,
        NgIf,
        MatOptionModule,
        MatProgressSpinnerModule,
        NgFor,
        NgClass,
        MatSelectModule,
        MatButtonModule,
        KeyValuePipe,
        TranslatePipe,
    ],
})
export class AddPermissionComponent implements OnChanges {
    private destroyRef = inject(DestroyRef);

    @Input() suggestions: Array<InheritedPermissionEntity> = [];

    @Input() addButtonLabel = '';

    @Input() searchPlaceholderText = '';

    @Input() loading = false;

    @Output() addNewPermission: EventEmitter<NewPermissionEntity> = new EventEmitter();

    // eslint-disable-next-line @angular-eslint/no-output-native
    @Output() search: EventEmitter<string> = new EventEmitter();

    form: FormGroup<AddPermissionForm>;

    selectedSuggestion?: InheritedPermissionEntity;
    protected permissionLabels = NewPermissionLabels;

    private readonly suggestionsSubject = new BehaviorSubject<PermissionEntity[]>([]);

    constructor(private isSuggestedPermissionEntityValidator: IsSuggestedPermissionEntityValidator) {
        this.form = new FormGroup<AddPermissionForm>(
            {
                search: new FormControl<string>('', {
                    validators: Validators.required,
                    asyncValidators: this.isSuggestedPermissionEntityValidator.createValidator(this.suggestionsSubject.asObservable()),
                    nonNullable: true,
                }),
                permission: new FormControl<NewPermission | undefined>(
                    { value: undefined, disabled: true },
                    {
                        validators: Validators.required,
                        nonNullable: true,
                    }
                ),
            },
            { validators: this.getDisableValidator.bind(this) }
        );
        this.form.controls.search.valueChanges
            .pipe(
                filter((text) => typeof text === 'string'),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe({
                next: (text) => {
                    this.search.emit(text.trim());
                },
            });
        this.destroyRef.onDestroy(() => {
            this.suggestionsSubject.complete();
        });
    }

    ngOnChanges(): void {
        this.suggestionsSubject.next(this.suggestions);
    }

    addPermission() {
        if (this.selectedSuggestion) {
            const { inheritedPermission, ...suggestedEntity } = this.selectedSuggestion;
            const newPermission: NewPermissionEntity = {
                ...suggestedEntity,
                permission: this.form.controls.permission.value as NewPermission,
            };
            this.form.controls.search.patchValue('');
            this.form.controls.search.markAsUntouched();
            this.form.controls.permission.patchValue(undefined);
            this.form.controls.permission.markAsUntouched();
            this.selectedSuggestion = undefined;
            this.form.controls.permission.disable();
            this.addNewPermission.emit(newPermission);
        }
    }

    selectSuggestion(event: MatAutocompleteSelectedEvent) {
        this.selectedSuggestion = event.option.value;
        if (this.selectedSuggestion) {
            this.permissionLabels = this.getAvailablePermissionsOptions(this.selectedSuggestion.inheritedPermission);
            this.form.controls.permission.enable();
        }
    }

    getEntityLabel(entity: PermissionEntity) {
        return entity?.entityLabel ?? '';
    }

    originalOrder = (): number => 0;

    protected suggestionTrackBy(_index: number, suggestion: PermissionEntity) {
        return suggestion.entityId;
    }

    private getAvailablePermissionsOptions(permission?: NewPermission) {
        if (!permission) {
            return NewPermissionLabels;
        }
        const levels: Permission[] = ['None', 'Read', 'ReadWrite', 'Everything'];
        const currentLevel = levels.indexOf(permission);
        const availableOptions: any = {};
        for (const [key, value] of Object.entries(NewPermissionLabels)) {
            const level = levels.indexOf(key as Permission);
            if (level > currentLevel) {
                availableOptions[key] = value;
            }
        }
        return availableOptions;
    }

    private getDisableValidator(): { [key: string]: any } | null {
        if (this.form?.controls?.permission?.disabled) {
            return { isStillDisabled: true };
        }

        return null;
    }
}

import { Component, DestroyRef, ElementRef, inject, OnInit, ViewChild } from '@angular/core';
import { MatDatepickerInputEvent, MatDatepickerModule } from '@angular/material/datepicker';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { isAfter, isBefore, isValid, parse } from 'date-fns';
import { CommonModule, DatePipe } from '@angular/common';
import { AbstractControl, FormControl, FormsModule, ReactiveFormsModule, ValidationErrors, ValidatorFn } from '@angular/forms';
import { CreatedDateFormType } from './created-date-search-filter.type';
import { CreatedDateSearchFilterService } from './created-date-search-filter.service';
import { Subject } from 'rxjs';
import { debounceTime } from 'rxjs/operators';
import { CreatedDateSearchFilterData } from './created-date-search-filter.data';
import { MatIconModule, MatIconRegistry } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatDividerModule } from '@angular/material/divider';
import { MatListModule, MatSelectionList } from '@angular/material/list';
import { MatInputModule } from '@angular/material/input';
import { MatMenuModule } from '@angular/material/menu';
import { FilterId, SearchFilterValueService } from '@alfresco/adf-hx-content-services/services';
import { DomSanitizer } from '@angular/platform-browser';
import { BaseSearchFilterDirective } from '../../directives/base-search-filter.directive';
import { SearchFilterContainerComponent } from '../search-filter-container/search-filter-container.component';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

export interface CreatedDateOption {
    label: string;
    date: string;
}

@Component({
    selector: 'hxp-search-created-date-filter',
    templateUrl: './created-date-search-filter.component.html',
    styleUrls: ['./created-date-search-filter.component.scss'],
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        MatButtonModule,
        MatDividerModule,
        MatDatepickerModule,
        MatFormFieldModule,
        MatIconModule,
        MatInputModule,
        MatListModule,
        MatMenuModule,
        ReactiveFormsModule,
        SearchFilterContainerComponent,
        TranslatePipe,
    ],
    providers: [CreatedDateSearchFilterService],
})
export class CreatedDateSearchFiltersComponent extends BaseSearchFilterDirective<CreatedDateFormType> implements OnInit {
    private readonly destroyRef = inject(DestroyRef);

    @ViewChild('afterDateInput') protected afterDateInput?: ElementRef;
    @ViewChild('beforeDateInput') protected beforeDateInput?: ElementRef;
    @ViewChild(MatSelectionList) selectionList?: MatSelectionList;

    public defaultCreatedDateOptions: CreatedDateOption[] = [
        {
            label: 'SEARCH.FILTERS.CREATED_DATE.OPTIONS.LAST_7_DAYS',
            date: 'LAST_7_DAYS',
        },
        {
            label: 'SEARCH.FILTERS.CREATED_DATE.OPTIONS.LAST_30_DAYS',
            date: 'LAST_30_DAYS',
        },
        {
            label: 'SEARCH.FILTERS.CREATED_DATE.OPTIONS.LAST_6_MONTHS',
            date: 'LAST_6_MONTHS',
        },
        {
            label: 'SEARCH.FILTERS.CREATED_DATE.OPTIONS.LAST_YEAR',
            date: 'LAST_YEAR',
        },
    ];

    protected beforeDateInputSubject = new Subject<void>();
    protected afterDateInputSubject = new Subject<void>();

    constructor(
        protected datePipe: DatePipe,
        protected override searchFilterValueService: SearchFilterValueService,
        protected createdDateSearchFilterService: CreatedDateSearchFilterService,
        private translate: TranslateService,
        private matIconRegistry: MatIconRegistry,
        private domSanitizer: DomSanitizer
    ) {
        super(searchFilterValueService);

        const icons: Record<string, string> = {
            search_calendar: 'assets/search-icons/Calendar_search.svg',
        };

        for (const [iconName, iconPath] of Object.entries(icons)) {
            this.matIconRegistry.addSvgIcon(iconName, this.domSanitizer.bypassSecurityTrustResourceUrl(iconPath));
        }
    }

    public get id(): FilterId {
        return 'CreatedDateSearchFiltersComponent';
    }

    ngOnInit() {
        this.beforeDateInputSubject.pipe(debounceTime(500), takeUntilDestroyed(this.destroyRef)).subscribe(() => {
            this.filterForm.get('beforeDate')?.updateValueAndValidity({ onlySelf: true, emitEvent: false });
        });

        this.afterDateInputSubject.pipe(debounceTime(500), takeUntilDestroyed(this.destroyRef)).subscribe(() => {
            this.filterForm.get('afterDate')?.updateValueAndValidity({ onlySelf: true, emitEvent: false });
        });
    }

    public toHXQL(data: CreatedDateSearchFilterData): string {
        return this.createdDateSearchFilterService.toHXQL(data);
    }

    afterDateFilter = (d: Date | null): boolean => {
        const beforeDate = this.filterForm.value.beforeDate;
        return !beforeDate || !d || isBefore(d, beforeDate);
    };

    beforeDateFilter = (d: Date | null): boolean => {
        const afterDate = this.filterForm.value.afterDate;
        return !afterDate || !d || isAfter(d, afterDate);
    };

    protected setData(data: CreatedDateSearchFilterData): void {
        try {
            for (const value of data?.values || []) {
                const beforeDate = value.beforeDate ? new Date(value.beforeDate) : null;
                const afterDate = value.afterDate ? new Date(value.afterDate) : null;
                if (afterDate || beforeDate) {
                    this.filterForm.patchValue({
                        isCustomDate: true,
                        afterDate,
                        beforeDate,
                    });
                    this.updateCustomDateSelectedValue();
                } else if (value['date']) {
                    this.createdDateValueChanged(value as CreatedDateOption);
                }
            }
        } catch (error) {
            console.error('Error while setting data for Created Date filter', error);
        }
    }

    protected getFormControls(): { [key: string]: AbstractControl } {
        return {
            defaultOption: new FormControl(null),
            isCustomDate: new FormControl(false),
            afterDate: new FormControl(null, [this.dateFormatValidator('afterDateInput'), this.afterDateValidator()]),
            beforeDate: new FormControl(null, [this.dateFormatValidator('beforeDateInput'), this.beforeDateValidator()]),
        };
    }

    protected dateFormatValidator(dateInputTypeLocator: string): ValidatorFn {
        return (): { [key: string]: any } | null => {
            const value = this[dateInputTypeLocator]?.nativeElement.value || '';
            const parsedDate = parse(value, 'MM/dd/yyyy', new Date());

            if (value && !isValid(parsedDate)) {
                return { invalidDateFormat: true };
            }

            return null;
        };
    }

    protected afterDateValidator(): ValidatorFn {
        return (control: AbstractControl): ValidationErrors | null => {
            const afterDate = control.value;
            const beforeDate = this.filterForm?.get('beforeDate')?.value;

            if (isAfter(afterDate, beforeDate)) {
                return { afterDateTooLate: true };
            }

            return null;
        };
    }

    protected beforeDateValidator(): ValidatorFn {
        return (control: AbstractControl): ValidationErrors | null => {
            const beforeDate = control.value;
            const afterDate = this.filterForm?.get('afterDate')?.value;

            if (isBefore(beforeDate, afterDate)) {
                return { beforeDateTooEarly: true };
            }

            return null;
        };
    }

    protected enableCustomDate(e: Event) {
        e.preventDefault();
        this.selectionList?.deselectAll();
        this.selectedValue = this.value;
        this.filterForm.patchValue({
            defaultOption: null,
            isCustomDate: true,
        });
    }

    protected createdDateValueChanged(data: CreatedDateOption): void {
        this.selectedValue = new CreatedDateSearchFilterData([data]);
        this.filterForm.patchValue({
            defaultOption: this.selectedValue,
            isCustomDate: false,
            afterDate: null,
            beforeDate: null,
        });
    }

    protected afterDateChanged(event: MatDatepickerInputEvent<Date>): void {
        this.filterForm.patchValue({
            afterDate: event.value,
        });
        this.updateCustomDateSelectedValue();
    }

    protected beforeDateChanged(event: MatDatepickerInputEvent<Date>): void {
        this.filterForm.patchValue({
            beforeDate: event.value,
        });
        this.updateCustomDateSelectedValue();
    }

    protected clearAfterDate(event: MouseEvent): void {
        event.stopPropagation();
        event.preventDefault();
        if (this.afterDateInput) {
            this.afterDateInput.nativeElement.value = '';
            this.filterForm.patchValue({
                afterDate: null,
            });
            this.updateCustomDateSelectedValue();
        }
    }

    protected clearBeforeDate(event: MouseEvent): void {
        event.stopPropagation();
        event.preventDefault();
        if (this.beforeDateInput) {
            this.beforeDateInput.nativeElement.value = '';
            this.filterForm.patchValue({
                beforeDate: null,
            });
            this.updateCustomDateSelectedValue();
        }
    }

    protected validateInput(event: KeyboardEvent) {
        const pattern = /[0-9+\-/]/;
        const inputChar = String.fromCharCode(event.charCode);

        if (!pattern.test(inputChar)) {
            event.preventDefault();
        }
    }

    private updateCustomDateSelectedValue(): void {
        let label = '';

        const { afterDate, beforeDate } = this.filterForm.value;

        if (afterDate && beforeDate) {
            label = this.translate.instant('SEARCH.FILTERS.CREATED_DATE.OPTIONS.CUSTOM_DATE.VALUES.SINCE_TO_DATE', {
                afterDate: this.datePipe.transform(afterDate, 'mediumDate'),
                beforeDate: this.datePipe.transform(beforeDate, 'mediumDate'),
            });
        } else if (afterDate && !beforeDate) {
            label = this.translate.instant('SEARCH.FILTERS.CREATED_DATE.OPTIONS.CUSTOM_DATE.VALUES.SINCE_TO_TODAY', {
                date: this.datePipe.transform(afterDate, 'mediumDate'),
            });
        } else if (!afterDate && beforeDate) {
            label = this.translate.instant('SEARCH.FILTERS.CREATED_DATE.OPTIONS.CUSTOM_DATE.VALUES.UNTIL_DATE', {
                date: this.datePipe.transform(beforeDate, 'mediumDate'),
            });
        }

        this.selectedValue = label
            ? new CreatedDateSearchFilterData([
                  {
                      label,
                      afterDate,
                      beforeDate,
                  },
              ])
            : this.value;
    }

    override discardPendingChanges(): void {
        super.discardPendingChanges();
        this.selectionList?.deselectAll();
    }

    override clearChanges(): void {
        super.clearChanges();
        this.selectionList?.deselectAll();
    }
}

import { Component, Inject } from '@angular/core';
import { FormBuilder, FormControlName, ReactiveFormsModule, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogModule } from '@angular/material/dialog';
import { Clipboard } from '@angular/cdk/clipboard';
import { ContentShareService, HxpNotificationService } from '@alfresco/adf-hx-content-services/services';
import { Document } from '@hylandsoftware/hxcs-js-client';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslatePipe } from '@ngx-translate/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSnackBarModule } from '@angular/material/snack-bar';
import { MatInputModule } from '@angular/material/input';

export interface DialogData {
    sharedDocument: Document;
}
const originFormControlNameNgOnChanges = FormControlName.prototype.ngOnChanges;
FormControlName.prototype.ngOnChanges = function (...arg) {
    const result = originFormControlNameNgOnChanges.apply(this, arg);
    (this.control as any).nativeElement = (this.valueAccessor as any)?._elementRef?.nativeElement;
    return result;
};

@Component({
    selector: 'hxp-alfresco-dbp-content-share-dialog',
    templateUrl: './content-share-dialog.component.html',
    styleUrls: ['./content-share-dialog.component.scss'],
    standalone: true,
    imports: [
        MatDialogModule,
        MatButtonModule,
        MatTooltipModule,
        MatIconModule,
        MatFormFieldModule,
        ReactiveFormsModule,
        MatInputModule,
        TranslatePipe,
        MatSnackBarModule,
    ],
})
export class ContentShareDialogComponent {
    readonly shareDocumentForm;

    constructor(
        private readonly _fb: FormBuilder,
        @Inject(MAT_DIALOG_DATA) public data: DialogData,
        public contentShareService: ContentShareService,
        private clipboard: Clipboard,
        private hxpNotificationService: HxpNotificationService
    ) {
        this.shareDocumentForm = this._fb.group({
            shared_link: ['', Validators.required],
        });

        if (this.data?.sharedDocument) {
            const sharedLink = this.contentShareService.getSingleContentShareLink(this.data.sharedDocument);
            this.shareDocumentForm.patchValue({ shared_link: sharedLink });
        }
    }
    onCopy() {
        this.clipboard.copy(this.shareDocumentForm.value.shared_link ?? '');
        (<any>this.shareDocumentForm.get('shared_link')).nativeElement.select();
        this.hxpNotificationService.openSnackBar('DOCUMENT_SHARE.SNACKBAR.SHARE.SUCCESS', 'done');
    }
}

import { Component, Inject, ViewEncapsulation } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { PermissionsPanelRequestService } from '@alfresco/adf-hx-content-services/services';
import { MatButtonModule } from '@angular/material/button';
import { TranslatePipe } from '@ngx-translate/core';
import { MatRadioModule } from '@angular/material/radio';
import { FormsModule } from '@angular/forms';

export interface DismissPermissionDialogData<T = any> {
    dialogTitle: string;
    dialogDescription: string;
    dialogRejectButton: string;
    dialogConfirmButton: string;
    permissionDialogRef?: MatDialogRef<T>;
}

export abstract class DismissPermission {
    protected abstract close(isEdited: boolean): void;
    protected abstract cancel(isEdited: boolean): void;
}

@Component({
    templateUrl: './confirmation-dialog.component.html',
    styleUrls: ['./confirmation-dialog.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
    imports: [MatDialogModule, MatButtonModule, MatRadioModule, FormsModule, TranslatePipe],
})
export class CancelPermissionDialogComponent {
    constructor(
        private dialogRef: MatDialogRef<CancelPermissionDialogComponent>,
        @Inject(MAT_DIALOG_DATA) readonly dialogData: DismissPermissionDialogData,
        private permissionsPanelRequestService: PermissionsPanelRequestService
    ) {}

    reject() {
        this.dialogRef.close();
    }

    confirm() {
        this.dialogRef.close();
        if (this.dialogData?.permissionDialogRef) {
            this.dialogData.permissionDialogRef.close();
        } else {
            this.permissionsPanelRequestService.requestClosePanel();
        }
    }
}

import { CardViewComponent, CardViewItem } from '@alfresco/adf-core';
import { Component, ChangeDetectionStrategy, computed, input, output, signal, viewChildren, effect } from '@angular/core';
import { Document } from '@hylandsoftware/hxcs-js-client';
import { MatExpansionModule, MatExpansionPanel } from '@angular/material/expansion';
import { MatButtonModule } from '@angular/material/button';
import { TranslatePipe } from '@ngx-translate/core';
import { SchemaTree } from '@alfresco/adf-hx-content-services/services';

interface GroupedProperty {
    schema: string;
    properties: CardViewItem[];
    expanded: boolean;
}

/**
 * Component presents document properties viewer container.
 *
 * To use the `MetadataSidebarContentComponent`, you need first to import the component in your module
 *
 * ```ts
 * import { MetadataSidebarContentComponent } from '@alfresco/adf-hx-content-services/ui';
 *
 * @NgModule({
 *     imports: [
 *         MetadataSidebarContentComponent
 *         ...
 *     ],
 *    [...]
 * })
 *
 * export class AppModule {}
 * ```
 *
 * Then use it in your Angular template as shown in the example below:
 *
 * @example
 * <hxp-metadata-sidebar-content
 *    [document]="document"
 *    [editable]="editable"
 *    [copyToClipboardAction]="copyToClipboardAction"
 *    [displayEmpty]="displayEmpty"
 *    [useChipsForMultiValueProperty]="useChipsForMultiValueProperty">
 * </hxp-metadata-sidebar-content>
 */
@Component({
    selector: 'hxp-metadata-sidebar-content',
    templateUrl: './metadata-sidebar-content.component.html',
    styleUrls: ['./metadata-sidebar-content.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [MatExpansionModule, CardViewComponent, MatButtonModule, TranslatePipe],
})
export class MetadataSidebarContentComponent {
    /**
     * The document to display the properties for.
     * @type {Document}
     * @required
     */
    document = input<Document>();

    /**
     * The properties to display in the card view.
     * @type {CardViewItem[]}
     * @default []
     *
     * ```ts
     * export interface CardViewItem {
     *      label: string;
     *      value: any;
     *      key: string;
     *      default?: any;
     *      type: string;
     *      displayValue: any;
     *      editable?: boolean;
     *      icon?: string;
     * }
     * ```
     *
     */
    properties = input<CardViewItem[]>([]);

    propertiesGroups = input<SchemaTree>([]);

    /**
     * Toggles whether or not to enable copy to clipboard action.
     * @type {boolean}
     * @default true
     */
    copyToClipboardAction = input(true);

    /**
     * Toggles whether to display empty values in the card view.
     * @type {boolean}
     * @default false
     */
    displayEmpty = input(true);

    /**
     * Toggles whether the edit button should be shown
     * @type {boolean}
     * @default false
     */
    editable = input(false);

    /**
     * Toggles whether or not to enable chips for multivalued properties.
     * @type {boolean}
     * @default true
     */
    useChipsForMultiValueProperty = input(true);

    /**
     * Toggles whether to display properties in a collapsible accordion.
     * When true, properties are shown in an expandable accordion with the first property's label as the header.
     * When false, properties are displayed directly without accordion wrapping.
     * @type {boolean}
     * @default false
     */
    collapsible = input(false);

    propertyUpdateRequest = output<boolean>();

    /**
     * Array of invalid field IDs that should trigger accordion expansion.
     * When set, accordions containing these fields will automatically expand.
     * @type {string[]}
     * @default []
     */
    invalidFieldIds = input<string[]>([]);

    private expansionPanels = viewChildren(MatExpansionPanel);

    private expandedStates = signal<boolean[]>([]);

    constructor() {
        // Effect to expand accordions containing invalid fields
        effect(() => {
            const invalidIds = this.invalidFieldIds();
            if (invalidIds.length > 0) {
                this.expandAccordionsWithInvalidFields(invalidIds);
            }
        });
    }

    protected groupedProperties = computed((): GroupedProperty[] => {
        const props = this.properties();
        const groups = this.propertiesGroups();

        return groups.map((group, index) => ({
            ...group,
            properties: this.getPropertiesForGroup(props, group.fields),
            expanded: index === 0,
        }));
    });

    protected allExpanded = computed(() => {
        const states = this.expandedStates();
        return states.length > 0 && states.every(Boolean);
    });

    private getPropertiesForGroup(properties: CardViewItem[], fields: Record<string, any>): CardViewItem[] {
        const keys = Object.keys(fields);
        return properties.filter((property) => keys.includes(property.key.split('.')[0]));
    }

    protected readonly multiValueSeparator = ', ';

    protected onPanelExpandedChange(): void {
        const panels = this.expansionPanels();
        this.expandedStates.set(panels.map((panel) => panel.expanded));
    }

    protected toggleAllAccordions(): void {
        const expandable = !this.allExpanded();
        const panels = this.expansionPanels();

        for (const panel of panels) {
            if (expandable) {
                panel.open();
            } else {
                panel.close();
            }
        }

        this.expandedStates.set(panels.map(() => expandable));
    }

    private expandAccordionsWithInvalidFields(invalidIds: string[]): void {
        const props = this.properties();
        const groups = this.propertiesGroups();
        const panels = this.expansionPanels();

        for (const [index, group] of groups.entries()) {
            if (!panels[index]) {
                continue;
            }

            const groupProperties = this.getPropertiesForGroup(props, group.fields);
            const hasInvalidField = groupProperties.some((prop) => invalidIds.includes(prop.key as string));

            if (hasInvalidField) {
                panels[index].open();
            }
        }

        this.expandedStates.set(panels.map((panel) => panel.expanded));
    }
}

