@use 'satori-like-styles' as satori;
@use 'mat-selectors' as ms;
@use '@angular/material' as mat;

%adf-property-value-font {
    line-height: 1.43rem;
    font-weight: 500;
}
$adfPropertyLabelFontSize: 0.86rem;

.hxp-metadata-panel:focus,
.hxp-metadata-panel-wrapper:focus,
.hxp-metadata-info-drawer-content:focus {
    outline: none;
}

.hxp-metadata-panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0;

    &_title {
        margin: 0;
        padding: 0;
        display: inline-block;
        text-overflow: ellipsis;
        overflow: hidden;
        font-size: satori.$hy-font-sizes-40;
    }
}

.hxp-metadata-panel-spinner-container {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.adf-info-drawer-layout.hxp-metadata-panel {
    display: flex;
    width: 420px;
    height: calc(100% - satori.$hy-spacing-32);
    background-color: var(--adf-theme-background-card-color);
    padding: satori.$hy-spacing-16;

    .adf-info-drawer-layout-content {
        position: relative;
        padding: 0;
        height: 100%;
    }

    .adf-info-drawer-layout-header {
        display: none;
    }
}

.adf-property-container adf-card-view-selectitem,
.adf-property-container adf-card-view-dateitem {
    .adf-property-value {
        margin-top: 0;
        padding-top: 0;
        @extend %adf-property-value-font;
    }
    .adf-property-label {
        line-height: 1.43rem;
        font-weight: 400;
        font-size: $adfPropertyLabelFontSize;
    }
}

.adf-viewer-sidebars .adf-viewer__sidebar {
    width: auto;
}

#{ms.$mat-form-field-subscript-wrapper},
#{ms.$mat-form-field-underline} {
    display: none;
}

#{ms.$mdc-text-field--filled} #{ms.$mat-floating-label} {
    .adf-property-label {
        font-size: calc(#{$adfPropertyLabelFontSize} / var(--mat-mdc-form-field-floating-label-scale));
    }
}

#{ms.$mat-mdc-form-field-infix} {
    display: flex;
    align-items: center;

    #{ms.$mat-mdc-form-field-input-control}.adf-property-value {
        @extend %adf-property-value-font;
    }
}

.hxp-metadata-info-drawer-content {
    height: 100%;
    flex-direction: column;

    // adf-info-drawer-layout forces display:block inline; keep flex so footer stays pinned
    display: flex !important;
}

.hxp-metadata-panel-wrapper {
    width: 100%;
    overflow-y: scroll;
    position: relative;
    display: flex;
    flex-direction: column;
    flex: 1;
    padding-top: satori.$hy-spacing-16;
}

.hxp-property-edit-actions {
    width: 100%;
    background-color: var(--theme-card-background-color);
    display: flex;
    justify-content: flex-end;
    gap: satori.$hy-spacing-16;
    padding-top: satori.$hy-spacing-16;
    border-top: 1px solid satori.$hy-colors-cool-gray-300;
    .hxp-cancel-button {
        color: var(--theme-primary-color, satori.$satori-like-primary);
        border: 0;
    }
}

// Ensure card-view labels adopt the active theme color palette
// The rule is defined in _hxp-inputs
// To be reviewed once we adopt MD3 (https://hyland.atlassian.net/browse/CSX-359)
// Disable stylelint for selector-class-pattern as we are targeting 3rd party library classes
/* stylelint-disable selector-class-pattern */
.mdc-text-field {
    &:not(&--focused, &--invalid) .adf-property-label {
        color: var(--theme-text-color) !important; /* Overrides color: unset !important in _hxp-inputs.scss:10 */
    }
}
/* stylelint-enable selector-class-pattern */

.hxp-required-field::after {
    content: ' *';
}

.hxp-metadata-sidebar-content-tab {
    margin: satori.$hy-spacing-16;
}

components.rawdescription:
Sidebar component to display and edit a Document properties.

To use the `HxpPropertiesSidebarComponent`, you need first to import the component in your module

```ts
import { HxpPropertiesSidebarComponent } from '@alfresco/adf-hx-content-services/ui';

@NgModule({
    imports: [
        HxpPropertiesSidebarComponent
        ...
    ],
   [...]
})

export class AppModule {}

```

Then use it in your Angular template as shown in the example below:

```html
<hxp-properties-sidebar [editable]="false" [document]="document" (closePropertySidebar)="onClose()">
```

