@if(isMetadataPanelFeatureFlagOn()) {
    <hxp-metadata-sidebar
        [document]="document"
        [editable]="editable"
        (closePropertySidebar)="onClosePropertySidebar()" />
} @else {
    <hxp-properties-sidebar-legacy
        [document]="document"
        [editable]="editable"
        (closePropertySidebar)="onClosePropertySidebar()" />
}

